char *uwsgi_expand_path(char *old_path, int old_path_len, char *new_path) { char path[4096]; memcpy(path, old_path, (size_t) old_path_len); path[old_path_len] = 0; char *ptr = new_path; if (!ptr) { ptr = uwsgi_malloc(sizeof(char) * 4096 + 1); } if (realpath(path, ptr) == NULL) { uwsgi_log("%realpath() of %s failed: %s [%s line %d]\n", path, strerror(__errno_location()->pos), "<stdin>", 'A'); if (!new_path) { free(ptr); } return NULL; } return ptr; }